-- PT104-S4-Q17. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT104-S4-Q17$batch11$ AND q.stimulus=$batch11$The Green Ensemble, a nonprofit theater group, has always been financially dependent on contributions from corporations and would have been forced to disband this year if any of its corporate sponsors had withdrawn their financial support. But the Green Ensemble has not only been able to continue in operation throughout the year, but has recently announced its schedule for next year.$batch11$ AND q.prompt=$batch11$Which one of the following is a conclusion that can be properly drawn from the information above?$batch11$ AND q.correct_choice=$batch11$A$batch11$) THEN RAISE EXCEPTION 'Question changed: PT104-S4-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT104-S4-Q17$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S4-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT104-S4-Q17$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$If any corporate sponsor had withdrawn support, the Green Ensemble would have been forced to disband this year. The group did not disband. It kept running and announced next year's schedule.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Sponsor withdrew → disband. The group didn't disband. Take the contrapositive: no sponsor withdrew.$batch11$), (2, $batch11$Goal$batch11$, $batch11$No corporate sponsor withdrew support this year.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT104-S4-Q17$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Withdrawal would have forced the group to disband. It didn't disband, so no sponsor withdrew.$batch11$), ($batch11$B$batch11$, $batch11$The group has "always been" dependent on corporations. Nothing says it found other money.$batch11$), ($batch11$C$batch11$, $batch11$We know funding didn't fall away. We don't know it rose.$batch11$), ($batch11$D$batch11$, $batch11$Dependence doesn't tell us what share of income came from corporations.$batch11$), ($batch11$E$batch11$, $batch11$The passage is about one group, not funding for theater groups in general.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT104-S4-Q17$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
